<?php declare(strict_types=1); require dirname(__DIR__).'/includes/bootstrap.php'; require ROOT_PATH.'/includes/members.php';if(!memberLoggedIn()){header('Location:'.url('members/login.php'));exit;}$member=currentMember();if(!$member){header('Location:'.url('members/logout.php'));exit;}$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!memberVerifyCsrf())$error='Your session expired. Please try again.';else{$name=trim((string)($_POST['display_name']??''));$bio=trim((string)($_POST['bio']??''));if(mb_strlen($name)<2||mb_strlen($name)>120||mb_strlen($bio)>500)$error='Use a display name of 2–120 characters and a profile note under 500 characters.';else{database()->prepare('UPDATE wts_members SET display_name=?,bio=? WHERE id=?')->execute([$name,$bio,$member['id']]);$member=currentMember();$message='Profile saved.';}}}$purchases=memberPurchases((int)$member['id']);$pageTitle='Your account | Word Truth Spirit';require ROOT_PATH.'/includes/header.php';?>
<main class="member-dashboard"><header><p class="kicker">Reader account</p><h1>Hello, <?=e((string)$member['display_name'])?></h1><p>Manage the identity attached to your comments and review PayPal checkout activity.</p></header><?php if($message):?><p class="notice success"><?=e($message)?></p><?php elseif($error):?><p class="notice error"><?=e($error)?></p><?php endif;?><div class="member-dashboard-grid"><section class="member-panel"><h2>Your profile</h2><p>Your public profile appears beside comments you post while signed in.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(memberCsrfToken())?>"><label>Display name<input name="display_name" maxlength="120" value="<?=e((string)$member['display_name'])?>" required></label><label>Profile note <small>Optional · up to 500 characters</small><textarea name="bio" rows="5" maxlength="500" placeholder="A few words about your interest in the conversation."><?=e((string)$member['bio'])?></textarea></label><button class="button button-primary">Save profile</button></form><p class="member-profile-link">Public profile: <a href="<?=url('members/profile.php?u='.urlencode((string)$member['profile_slug']))?>">View profile</a></p></section><section class="member-panel"><h2>Checkout activity</h2><p class="member-history-note">Pending means we opened a PayPal checkout. It is not a receipt; payment status requires PayPal verification.</p><?php if($purchases):?><div class="purchase-history"><?php foreach($purchases as $purchase):?><article><div><strong><?=e($purchase['product_name'])?></strong><small><?=date('M j, Y',strtotime($purchase['created_at']))?></small></div><div><strong><?=e(formatMoney((float)$purchase['amount'],(string)$purchase['currency']))?></strong><span class="status-pill status-<?=e($purchase['status'])?>"><?=e($purchase['status'])?></span></div></article><?php endforeach;?></div><?php else:?><div class="member-empty"><span>◇</span><p>No checkout activity yet.</p><a href="<?=url('shop/')?>">Explore shop &amp; giving →</a></div><?php endif;?></section></div></main><?php require ROOT_PATH.'/includes/footer.php'; ?>
